import { describe, expect, it } from "vitest";
import { computeFrenzy, levelFromScore, normalizeWeights } from "../src/lib/engines/fishing";
import { DEFAULT_CONFIG } from "../src/lib/config";

describe("IF engine", () => {
  it("sums factor points to a 0-100 score when all data is present", () => {
    const r = computeFrenzy({
      waterTempC: 14.5,
      waterDelta24h: 0.1,
      pressure: { current: 1014, h3: 1015, h6: 1016, h12: 1017, h24: 1018 },
      windKmh: 14,
      gustKmh: 18,
      cloudPct: 72,
      precipMm: 0,
      hour: 18,
      historicalScore: 70,
      historicalDetail: "test",
      weights: DEFAULT_CONFIG.weights,
    });
    expect(r.total).not.toBeNull();
    expect(r.total!).toBeGreaterThan(70);
    expect(r.total!).toBeLessThanOrEqual(100);
    expect(r.factors.reduce((a, f) => a + f.points, 0)).toBe(r.total);
  });

  it("does not invent a score when everything is missing", () => {
    const r = computeFrenzy({
      waterTempC: null,
      pressure: { current: null, h3: null, h6: null, h12: null, h24: null },
      windKmh: null,
      cloudPct: null,
      historicalScore: null,
      historicalDetail: "none",
      weights: DEFAULT_CONFIG.weights,
    });
    expect(r.total).toBeNull();
    expect(r.factors.every((f) => !f.available)).toBe(true);
  });

  it("renormalizes weights when historical is missing", () => {
    const n = normalizeWeights(DEFAULT_CONFIG.weights, {
      water: true,
      pressure: true,
      wind: true,
      cloud: true,
      historical: false,
    });
    const sum = n.water + n.pressure + n.wind + n.cloud + n.historical;
    expect(n.historical).toBe(0);
    expect(sum).toBeCloseTo(1, 5);
  });

  it("maps configurable thresholds", () => {
    expect(levelFromScore(10, DEFAULT_CONFIG.levels)).toBe("TRES_MAUVAIS");
    expect(levelFromScore(30, DEFAULT_CONFIG.levels)).toBe("FAIBLE");
    expect(levelFromScore(50, DEFAULT_CONFIG.levels)).toBe("MOYEN");
    expect(levelFromScore(70, DEFAULT_CONFIG.levels)).toBe("BON");
    expect(levelFromScore(80, DEFAULT_CONFIG.levels)).toBe("TRES_BON");
    expect(levelFromScore(95, DEFAULT_CONFIG.levels)).toBe("EXCEPTIONNEL");
  });
});

import { describe, expect, it } from "vitest";
import {
  analogDistance,
  catchRateOnAnalogs,
  findAnalogs,
  historicalFactor,
  type DailyClimate,
} from "../src/lib/engines/historical";

const day = (date: string, extra: Partial<DailyClimate> = {}): DailyClimate => ({
  date,
  airTempC: 18,
  pressureHpa: 1015,
  pressureDelta: -2,
  windKmh: 12,
  windDirDeg: 270,
  cloudPct: 70,
  ...extra,
});

describe("historical matching", () => {
  it("finds close meteorological analogs", () => {
    const archive = [
      day("2024-09-01"),
      day("2023-09-04", { airTempC: 18.2 }),
      day("2022-01-01", { airTempC: 4, pressureHpa: 1030, windKmh: 2, cloudPct: 10 }),
    ];
    const r = findAnalogs(day("2026-09-04"), archive, []);
    expect(r.similarCount).toBeGreaterThan(0);
    expect(r.analogs[0].date).not.toBe("2022-01-01");
  });

  it("does not invent a catch probability without catches", () => {
    const analogs = findAnalogs(day("2026-09-04"), [day("2024-09-01"), day("2023-09-04")], []).analogs;
    expect(catchRateOnAnalogs(analogs).rate).toBeNull();
  });

  it("returns null historical score if archive is too short", () => {
    expect(historicalFactor({ similarCount: 3, meanDistance: 0.1, archiveDays: 5 }).score).toBeNull();
  });

  it("distance is 0 for identical days (except date)", () => {
    const a = day("2024-09-04");
    const b = day("2025-09-04");
    expect(analogDistance(a, b)).toBeLessThan(0.05);
  });
});

import { describe, expect, it } from "vitest";
import { pressureDeltas, scorePressure } from "../src/lib/engines/pressure";

describe("pressure", () => {
  it("computes 3/6/12/24h deltas", () => {
    const d = pressureDeltas({
      current: 1012,
      h3: 1013,
      h6: 1014,
      h12: 1016,
      h24: 1018,
    });
    expect(d.d12).toBe(-4);
    expect(d.d24).toBe(-6);
  });

  it("scores a moderate drop higher than a isolated 1015 hPa", () => {
    const drop = scorePressure({
      current: 1014,
      h3: 1015,
      h6: 1016,
      h12: 1017,
      h24: 1018,
    });
    const isolated = scorePressure({
      current: 1015,
      h3: null,
      h6: null,
      h12: null,
      h24: null,
    });
    expect(drop.available).toBe(true);
    expect(drop.score).toBeGreaterThan(isolated.score);
  });

  it("returns unavailable when current is missing", () => {
    const r = scorePressure({
      current: null,
      h3: 1015,
      h6: 1015,
      h12: 1015,
      h24: 1015,
    });
    expect(r.available).toBe(false);
    expect(r.detail).toBe("Donnée indisponible");
  });
});

import { describe, expect, it } from "vitest";
import { analyzeCatches, empiricalSpeciesShift } from "../src/lib/engines/stats";
import { applyWaterMeasure } from "../src/lib/engines/water";
import type { CatchRecord } from "../src/lib/types";

function catchAt(hour: string, ifScore: number, species: CatchRecord["species"] = "brochet"): CatchRecord {
  return {
    id: hour,
    date: "2026-09-01",
    time: hour,
    lat: null,
    lon: null,
    species,
    lengthCm: 70,
    weightKg: null,
    lure: "",
    technique: "",
    depthM: null,
    comment: "",
    photoPath: null,
    weatherSnapshot: {
      airTempC: 18,
      waterTempC: 16,
      pressureHpa: 1014,
      windKmh: 12,
      windCardinal: "O",
      cloudPct: 70,
      ifScore,
    },
    createdAt: "2026-09-01T10:00:00.000Z",
  };
}

describe("local stats", () => {
  it("does not invent catch probability with empty journal", () => {
    const s = analyzeCatches([]);
    expect(s.n).toBe(0);
    expect(s.ready).toBe(false);
    expect(s.alignment.ready).toBe(false);
  });

  it("computes hour histogram and mean IF", () => {
    const s = analyzeCatches([
      catchAt("18:00", 80),
      catchAt("18:30", 82),
      catchAt("07:00", 60),
      catchAt("18:10", 78),
      catchAt("19:00", 84),
    ]);
    expect(s.n).toBe(5);
    expect(s.ready).toBe(true);
    expect(s.byHour[18]).toBe(3);
    expect(s.meanIfAtCatch).toBeGreaterThan(70);
  });

  it("keeps species uncalibrated under 8 catches", () => {
    expect(empiricalSpeciesShift([catchAt("18:00", 80)], "brochet", 18).calibrated).toBe(false);
  });
});

describe("water measure overlay", () => {
  const est = {
    value: 19,
    kind: "estimation" as const,
    confidence: "moyenne" as const,
    note: "est",
  };

  it("uses a fresh in-situ measure as MESURE", () => {
    const r = applyWaterMeasure(est, {
      id: "1",
      tempC: 17.2,
      at: new Date().toISOString(),
      source: "pecheur",
      note: "",
    });
    expect(r.kind).toBe("mesure");
    expect(r.value).toBe(17.2);
    expect(r.measured).toBe(true);
  });

  it("does not present a 2-day-old measure as current", () => {
    const old = new Date(Date.now() - 48 * 3600_000).toISOString();
    const r = applyWaterMeasure(est, {
      id: "1",
      tempC: 12,
      at: old,
      source: "pecheur",
      note: "",
    });
    expect(r.kind).toBe("estimation");
    expect(r.measured).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import { climatologyAt, estimateWaterTempC, scoreWater } from "../src/lib/engines/water";

describe("water engine", () => {
  it("never treats air as a measurement of water", () => {
    const est = estimateWaterTempC({
      at: new Date("2026-09-04T12:00:00"),
      airMean5d: 28,
      airNow: 30,
    });
    expect(est.kind).toBe("estimation");
    expect(est.value).toBeLessThan(28);
  });

  it("uses climatology fallback with low confidence", () => {
    const est = estimateWaterTempC({
      at: new Date("2026-01-15T12:00:00Z"),
      airMean5d: null,
      airNow: null,
    });
    expect(est.confidence).toBe("faible");
    expect(est.value).toBeCloseTo(climatologyAt(new Date("2026-01-15T12:00:00Z")), 0);
  });

  it("scores the V1 optimal band highest", () => {
    const good = scoreWater({ tempC: 14 });
    const hot = scoreWater({ tempC: 27 });
    const missing = scoreWater({ tempC: null });
    expect(good.score).toBeGreaterThan(hot.score);
    expect(missing.available).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import { scoreWind, toCardinal, windVector } from "../src/lib/engines/wind";

describe("wind", () => {
  it("uses French cardinals", () => {
    expect(toCardinal(0)).toBe("N");
    expect(toCardinal(90)).toBe("E");
    expect(toCardinal(180)).toBe("S");
    expect(toCardinal(270)).toBe("O");
    expect(toCardinal(225)).toBe("SO");
  });

  it("stores a vector", () => {
    const v = windVector(10, 270);
    expect(v.u).not.toBe(0);
    expect(Number.isFinite(v.v)).toBe(true);
  });

  it("prefers moderate wind over flat calm or storm", () => {
    const mid = scoreWind({ speedKmh: 14 });
    const calm = scoreWind({ speedKmh: 1 });
    const storm = scoreWind({ speedKmh: 55 });
    expect(mid.score).toBeGreaterThan(calm.score);
    expect(mid.score).toBeGreaterThan(storm.score);
  });

  it("does not invent wind", () => {
    expect(scoreWind({ speedKmh: null }).available).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import { bestFishingWindows, nowHourIndex } from "../src/lib/engines/explain";

describe("best fishing windows", () => {
  const series = [
    { time: "2026-09-04T14:00:00", ifScore: 70 },
    { time: "2026-09-04T15:00:00", ifScore: 71 },
    { time: "2026-09-04T18:00:00", ifScore: 82 },
    { time: "2026-09-04T19:00:00", ifScore: 84 },
    { time: "2026-09-04T20:00:00", ifScore: 80 },
    { time: "2026-09-04T21:00:00", ifScore: 68 },
    { time: "2026-09-05T02:00:00", ifScore: 83 },
    { time: "2026-09-05T03:00:00", ifScore: 81 },
  ];

  it("keeps local peaks instead of a long gold band", () => {
    const flat = Array.from({ length: 20 }, (_, i) => ({
      time: `2026-09-04T${String(i).padStart(2, "0")}:00:00`,
      ifScore: 77 + (i === 8 ? 6 : i === 15 ? 5 : 0),
    }));
    const w = bestFishingWindows(flat);
    expect(w.length).toBeLessThanOrEqual(3);
    expect(w.some((x) => x.peak === 83)).toBe(true);
  });

  it("marks consecutive high hours as windows and keeps the peak", () => {
    const w = bestFishingWindows(series);
    expect(w.length).toBeGreaterThanOrEqual(2);
    expect(w[0].peak).toBe(84);
    expect(w[0].from).toBe("2026-09-04T18:00:00");
    expect(w[0].to).toBe("2026-09-04T20:00:00");
  });

  it("returns nothing when scores are missing", () => {
    expect(bestFishingWindows([{ time: "x", ifScore: null }])).toEqual([]);
  });

  it("finds the hour closest to now", () => {
    const idx = nowHourIndex(series, new Date("2026-09-04T19:10:00").getTime());
    expect(series[idx].time).toBe("2026-09-04T19:00:00");
  });
});

